@Override
	public void onNeighborBlockChange(World world, int x, int y, int z, Block block) {
		if(world.isBlockIndirectlyGettingPowered(x, y, z)) {
			int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );
			if(meta < 4) {
				world.setBlockMetadataWithNotify(x, y, z, meta + 4, 2);

				int i = BlockSeal.getFrameSize(world, x, y, z);

				if(i != 0)
					if(BlockSeal.isSealClosed(world, x, y, z, i))
						BlockSeal.openSeal(world, x, y, z, i);
					else
						BlockSeal.closeSeal(world, x, y, z, i);
			}
		} else {
			int meta = com.hbm.world.WorldBlockState.metadata(com.hbm.world.WorldBlockState.read(world, x, y, z) );
			if(meta >= 4) {
				world.setBlockMetadataWithNotify(x, y, z, meta % 4, 2);
			}
		}
	}

@Override
		public void update() {

			this.prevSpin = this.spin;

			if(this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ())) {
				if(!this.world.isRemote) {
					CBT_Atmosphere atmosphere = ChunkAtmosphereManager.proxy.getAtmosphere(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ());
					hasAtmosphere = atmosphere != null && atmosphere.getPressure() > 0.01D;
				}

				if(hasAtmosphere) {
					ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());

					int range = 10;
					int effRange = 0;
					double push = 0.1;

					for(int i = 1; i <= range; i++) {
						Block block = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + dir.offsetX * i, this.pos.getY() + dir.offsetY * i, this.pos.getZ() + dir.offsetZ * i).getBlock();
						boolean blowable = block instanceof IBlowable;

						if(block.isNormalCube() || blowable) {
							if(!this.world.isRemote && blowable)
								((IBlowable) block).applyFan(this.world, this.pos.getX() + dir.offsetX * i, this.pos.getY() + dir.offsetY * i, this.pos.getZ() + dir.offsetZ * i, dir, i);

							break;
						}

						effRange = i;
					}

					int x = dir.offsetX * effRange;
					int y = dir.offsetY * effRange;
					int z = dir.offsetZ * effRange;

					List<Entity> affected = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(this.pos.getX() + 0.5 + Math.min(x, 0), this.pos.getY() + 0.5 + Math.min(y, 0), this.pos.getZ() + 0.5 + Math.min(z, 0), this.pos.getX() + 0.5 + Math.max(x, 0), this.pos.getY() + 0.5 + Math.max(y, 0), this.pos.getZ() + 0.5 + Math.max(z, 0)).expand(0.5, 0.5, 0.5));

					for(Entity e : affected) {

						double coeff = push;

						if(falloff) {
							double dist = e.getDistance(this.pos.getX() + 0.5, this.pos.getY() + 0.5, this.pos.getZ() + 0.5);
							coeff *= 1.5 * (1 - dist / range / 2);
						}

						e.motionX += dir.offsetX * coeff;
						e.motionY += dir.offsetY * coeff;
						e.motionZ += dir.offsetZ * coeff;
					}

					if(this.world.isRemote && this.world.rand.nextInt(30) == 0) {
						double speed = 0.2;
						this.world.spawnParticle("cloud", this.pos.getX() + 0.5 + dir.offsetX * 0.5, this.pos.getY() + 0.5 + dir.offsetY * 0.5, this.pos.getZ() + 0.5 + dir.offsetZ * 0.5, dir.offsetX * speed, dir.offsetY * speed, dir.offsetZ * speed);
					}
				}

				this.spin += 30;
			}

			if(this.spin >= 360) {
				this.prevSpin -= 360;
				this.spin -= 360;
			}

			if(!this.world.isRemote) {
				networkPackNT(150);
			}
		}

@Override
	public void onNeighborBlockChange(World world, int x, int y, int z, Block neighbor) {
		super.onNeighborBlockChange(world, x, y, z, neighbor);
		if (world.isRemote) return;
		int[] core = this.findCore(world, x, y, z);
		if (core == null) return;
		int cx = core[0];
		int cy = core[1];
		int cz = core[2];
		TileEntity te = world.getTileEntity(new net.minecraft.util.math.BlockPos(cx, cy, cz));
		if (!(te instanceof TileEntityReactorZirnox)) return;
		TileEntityReactorZirnox reactor = (TileEntityReactorZirnox) te;
		boolean powered = false;
		// 2. Scan multiblock
		for (int dx = -2; dx <= 2 && !powered; dx++) {
			for (int dy = 0; dy <= 4 && !powered; dy++) {
				for (int dz = -2; dz <= 2 && !powered; dz++) {
					// Get only surface blocks
					if (dx == -2 || dx == 2 ||
						dy == 0  || dy == 4 ||
						dz == -2 || dz == 2) {

						int sx = cx + dx;
						int sy = cy + dy;
						int sz = cz + dz;

						if (world.isBlockIndirectlyGettingPowered(sx, sy, sz) ||
							world.getBlockPowerInput(sx, sy, sz) > 0) {

							powered = true;
							break;
						}
					}
				}
			}
		}
		reactor.setRedstonePowered(powered);
	}

