public void updateRedstonePower(int x, int y, int z) {
		//Drillgon200: Best I could come up with without having to use dummy tile entities
		BlockPos pos = new BlockPos(x, y, z);
		boolean powered = this.world.isBlockIndirectlyGettingPowered(x, y, z);
		boolean contained = activatedBlocks.contains(pos);
		if(!contained && powered) {
			activatedBlocks.add(pos);
			if(redstonePower == -1) {
				redstonePower = 0;
			}
			redstonePower++;
		} else if(contained && !powered) {
			activatedBlocks.remove(pos);
			redstonePower--;
			if(redstonePower == 0) {
				redstonePower = -1;
			}
		}
	}

@Override
	public void update() {

		if (!this.world.isRemote) {

			updateTypes();

			tanks[0].loadTank(2, 6, slots);
			tanks[1].loadTank(3, 7, slots);

			power = Library.chargeTEFromItems(slots, 5, power, maxPower);

			if(slots[4] != null && slots[4].getItem() == ModItems.rocket_fuel && solid + 250 <= maxSolid) {

				this.decrStackSize(4, 1);
				solid += 250;
			}

			if(this.world.getTotalWorldTime() % 20 == 0)
				this.updateConnections();

			networkPackNT(50);

			MissileStruct multipart = getStruct(slots[0]);

			if(multipart != null)
				PacketDispatcher.wrapper.sendToAllAround(new TEMissileMultipartPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), multipart), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 250));
			else
				PacketDispatcher.wrapper.sendToAllAround(new TEMissileMultipartPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), new MissileStruct()), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 250));

			outer:
			for(int x = -1; x <= 1; x++) {
				for(int z = -1; z <= 1; z++) {

					if(this.world.isBlockIndirectlyGettingPowered(this.pos.getX() + x, this.pos.getY(), this.pos.getZ() + z) && canLaunch()) {
						launchFromDesignator();
						break outer;
					}
				}
			}
		} else {

			List<Entity> entities = this.world.getEntitiesWithinAABBExcludingEntity(null, AxisAlignedBB.getBoundingBox(this.pos.getX() - 0.5, this.pos.getY(), this.pos.getZ() - 0.5, this.pos.getX() + 1.5, this.pos.getY() + 10, this.pos.getZ() + 1.5));

			for(Entity e : entities) {

				if(e instanceof EntityMissileCustom) {

					for(int i = 0; i < 15; i++) {

						boolean dir = this.world.rand.nextBoolean();
						float moX = (float) (dir ? 0 : this.world.rand.nextGaussian() * 0.5F);
						float moZ = (float) (!dir ? 0 : this.world.rand.nextGaussian() * 0.5F);

						NBTTagCompound data = new NBTTagCompound();
						data.setDouble("posX", this.pos.getX() + 0.5);
						data.setDouble("posY", this.pos.getY() + 0.25);
						data.setDouble("posZ", this.pos.getZ() + 0.5);
						data.setString("type", "launchSmoke");
						data.setDouble("moX", moX);
						data.setDouble("moY", 0);
						data.setDouble("moZ", moZ);
						MainRegistry.proxy.effectNT(data);
					}

					break;
				}
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			if(this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ()) && !message.isEmpty() && charges > 0) {

				delay--;

				if(delay <= 0) {
					delay = 30;

					int c = (int)(message.charAt(index));

					int mod = index % 9;

					double offX = (mod / 3 - 1) * 0.3125;
					double offZ = (mod % 3 - 1) * 0.3125;

					EntityFireworks fireworks = new EntityFireworks(this.world, this.pos.getX() + 0.5 + offX, this.pos.getY() + 1.5, this.pos.getZ() + 0.5 + offZ, color, c);
					this.world.spawnEntityInWorld(fireworks);

					this.world.playSoundAtEntity(fireworks, "hbm:weapon.rocketFlame", 3.0F, 1.0F);

					charges--;
					this.markDirty();

					NBTTagCompound data = new NBTTagCompound();
					data.setString("type", "vanillaExt");
					data.setString("mode", "flame");
					PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, this.pos.getX() + 0.5 + offX, this.pos.getY() + 1.125, this.pos.getZ() + 0.5 + offZ), new TargetPoint(this.world.provider.getDimension(), this.pos.getX() + 0.5 + offX, this.pos.getY() + 1.125, this.pos.getZ() + 0.5 + offZ, 100));

					index++;

					if(index >= message.length()) {
						index = 0;
						delay = 100;
					}
				}

			} else {
				delay = 0;
				index = 0;
			}
		}
	}

