public void generate() {

		if(this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ())) return;

		if(hasAcceptableFuel()) {
			if (tank.getFill() > 0 && breatheAir(1)) {

				this.wasOn = true;

				tank.setFill(tank.getFill() - 1);
				if(tank.getFill() < 0)
					tank.setFill(0);

				if(this.world.getTotalWorldTime() % 5 == 0) {
					super.pollute(tank.getTankType(), FluidReleaseType.BURN, 5F);
				}

				if(power + getHEFromFuel() <= powerCap) {
					power += getHEFromFuel();
				} else {
					power = powerCap;
				}
			}
		}
	}

private boolean isMultiblockRedstonePowered() {
		for (DirPos conPos : getConPos()) {
			BlockPos pos = conPos.offset(conPos.getDir().getOpposite());
			if(this.world.isBlockIndirectlyGettingPowered(pos.getX(), pos.getY(), pos.getZ())) {
				return true;
			}
		}
		return false;
	}

@Override
	public void update() {

		if(!this.world.isRemote) {
			int id = Arrays.asList(TrackType.values()).indexOf(getCurrentType());

			if(getCurrentType().name().equals(TrackType.NULL.name())) {
				PacketDispatcher.wrapper.sendToAllAround(new TESirenPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), id, false), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1500));
				return;
			}

			boolean active = this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ());

			if(getCurrentType().getType().name().equals(SoundType.LOOP.name())) {

				PacketDispatcher.wrapper.sendToAllAround(new TESirenPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), id, active), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1500));
			} else {

				if(!lock && active) {
					lock = true;
					PacketDispatcher.wrapper.sendToAllAround(new TESirenPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), id, false), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1500));
					PacketDispatcher.wrapper.sendToAllAround(new TESirenPacket(this.pos.getX(), this.pos.getY(), this.pos.getZ(), id, true), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 1500));
				}

				if(lock && !active) {
					lock = false;
				}
			}
		}
	}

@Override
	public void update() {

		if(!this.world.isRemote) {

			this.output = 0;
			this.consumption = 0;

			//meta below 12 means that it's an old multiblock configuration
			if(this.getBlockMetadata() < 12) {
				//get old direction
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata());
				//remove tile from the world to prevent inventory dropping
				this.world.removeTileEntity(this.pos.getX(), this.pos.getY(), this.pos.getZ());
				//use fillspace to create a new multiblock configuration
				this.world.setBlock(this.pos.getX(), this.pos.getY(), this.pos.getZ(), ModBlocks.machine_turbofan, dir.ordinal() + 10, 3);
				MultiblockHandlerXR.fillSpace(this.world, this.pos.getX(), this.pos.getY(), this.pos.getZ(), ((BlockDummyable) ModBlocks.machine_turbofan).getDimensions(), ModBlocks.machine_turbofan, dir);
				//restore connections
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() + dir.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() + dir.offsetX - rot.offsetX, this.pos.getY(), this.pos.getZ() + dir.offsetZ - rot.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() - dir.offsetX, this.pos.getY(), this.pos.getZ() - dir.offsetZ);
				((BlockDummyable) ModBlocks.machine_turbofan).makeExtra(this.world, this.pos.getX() - dir.offsetX - rot.offsetX, this.pos.getY(), this.pos.getZ() - dir.offsetZ - rot.offsetZ);
				//load the tile data to restore the old values
				NBTTagCompound data = new NBTTagCompound();
				this.writeToNBT(data);
				this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX(), this.pos.getY(), this.pos.getZ())).readFromNBT(data);
				return;
			}

			tank.setType(4, slots);
			tank.loadTank(0, 1, slots);
			blood.setTankType(Fluids.BLOOD);

			this.wasOn = false;

			upgradeManager.checkSlots(this, slots, 2, 2);
			this.afterburner = upgradeManager.getLevel(UpgradeType.AFTERBURN);

			if(slots[2] != null && slots[2].getItem() == ModItems.flame_pony)
				this.afterburner = 100;

			long burnValue = 0;
			int amount = 1 + this.afterburner;

			boolean redstone = false;

			for(DirPos pos : getConPos()) {
				if(this.world.isBlockIndirectlyGettingPowered(pos.getX(), pos.getY(), pos.getZ())) {
					redstone = true;
					break;
				}
			}

			int amountToBurn = 0;

			if(!redstone) {

				if(tank.getTankType().hasTrait(FT_Combustible.class) && tank.getTankType().getTrait(FT_Combustible.class).getGrade() == FuelGrade.AERO) {
					burnValue = tank.getTankType().getTrait(FT_Combustible.class).getCombustionEnergy() / 1_000;
				}

				amountToBurn = Math.min(amount, this.tank.getFill());
				if(amountToBurn > 0 && !breatheAir(amountToBurn)) amountToBurn = 0;

				if(amountToBurn > 0) {
					this.wasOn = true;
					this.tank.setFill(this.tank.getFill() - amountToBurn);
					this.output = (int) (burnValue * amountToBurn * (1 + Math.min(this.afterburner / 3D, 4)));
					this.power += this.output;
					this.consumption = amountToBurn;

					if(this.world.getTotalWorldTime() % 20 == 0) super.pollute(tank.getTankType(), FluidTrait.FluidReleaseType.BURN, amountToBurn * 5);;
				}
			}

			power = Library.chargeItemsFromTE(slots, 3, power, power);

			for(DirPos pos : getConPos()) {
				this.tryProvide(this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.trySubscribe(tank.getTankType(), this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				if(this.blood.getFill() > 0) this.sendFluid(blood, this.world, pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
				this.sendSmoke(pos.getX(), pos.getY(), pos.getZ(), pos.getDir());
			}

			if(burnValue > 0 && amountToBurn > 0) {

				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10).getRotation(ForgeDirection.UP);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				if(this.afterburner > 0) {

					for(int i = 0; i < 2; i++) {
						double speed = 2 + this.world.rand.nextDouble() * 3;
						double deviation = this.world.rand.nextGaussian() * 0.2;
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "gasfire");
						data.setDouble("mX", -dir.offsetX * speed + deviation);
						data.setDouble("mZ", -dir.offsetZ * speed + deviation);
						data.setFloat("scale", 8F);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, this.pos.getX() + 0.5F - dir.offsetX * (3 - i), this.pos.getY() + 1.5F, this.pos.getZ() + 0.5F - dir.offsetZ * (3 - i)), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
					}

					/*if(this.afterburner > 90 && worldObj.rand.nextInt(60) == 0) {
						worldObj.newExplosion(null, xCoord + 0.5 + dir.offsetX * 3.5, yCoord + 0.5, zCoord + 0.5 + dir.offsetZ * 3.5, 3F, false, false);
					}*/

					if(this.afterburner > 90 && this.world.rand.nextInt(30) == 0) {
						com.hbm.sound.WorldSoundEffects.play(this.world, this.pos.getX() + 0.5, this.pos.getY() + 1.5, this.pos.getZ() + 0.5, "hbm:block.damage", 3.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);
					}

					if(this.afterburner > 90) {
						NBTTagCompound data = new NBTTagCompound();
						data.setString("type", "gasfire");
						data.setDouble("mY", 0.1 * this.world.rand.nextDouble());
						data.setFloat("scale", 4F);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data,
								this.pos.getX() + 0.5F + dir.offsetX * (this.world.rand.nextDouble() * 4 - 2) + rot.offsetX * (this.world.rand.nextDouble() * 2 - 1),
								this.pos.getY() + 1F + this.world.rand.nextDouble() * 2,
								this.pos.getZ() + 0.5F - dir.offsetZ * (this.world.rand.nextDouble() * 4 - 2) + rot.offsetZ * (this.world.rand.nextDouble() * 2 - 1)
								), new TargetPoint(this.world.provider.getDimension(), this.pos.getX(), this.pos.getY(), this.pos.getZ(), 150));
					}
				}

				double minX = this.pos.getX() + 0.5 - dir.offsetX * 3.5 - rot.offsetX * 1.5;
				double maxX = this.pos.getX() + 0.5 - dir.offsetX * 19.5 + rot.offsetX * 1.5;
				double minZ = this.pos.getZ() + 0.5 - dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				double maxZ = this.pos.getZ() + 0.5 - dir.offsetZ * 19.5 + rot.offsetZ * 1.5;

				List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {

					if(this.afterburner > 0) {
						e.setFire(5);
						e.attackEntityFrom(DamageSource.onFire, 5F);
					}
					e.motionX -= dir.offsetX * 0.2;
					e.motionZ -= dir.offsetZ * 0.2;
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 8.5 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 8.5 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					e.motionX -= dir.offsetX * 0.2;
					e.motionZ -= dir.offsetZ * 0.2;
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 3.75 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.75 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					e.attackEntityFrom(ModDamageSource.turbofan, 1000);
					e.setInWeb();

					if(!e.isEntityAlive() && e instanceof EntityLivingBase) {
						NBTTagCompound vdat = new NBTTagCompound();
						vdat.setString("type", "giblets");
						vdat.setInteger("ent", e.getEntityId());
						vdat.setInteger("cDiv", 5);
						PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(vdat, e.posX, e.posY + e.height * 0.5, e.posZ), new TargetPoint(e.dimension, e.posX, e.posY + e.height * 0.5, e.posZ, 150));

						com.hbm.sound.VanillaWorldSoundEffects.play(this.world, e.posX, e.posY, e.posZ, "mob.zombie.woodbreak", 2.0F, 0.95F + this.world.rand.nextFloat() * 0.2F);

						blood.setFill(blood.getFill() + 50);
						if(blood.getFill() > blood.getMaxFill()) {
							blood.setFill(blood.getMaxFill());
						}
						this.showBlood = true;
					}
				}
			}

			if(this.power > this.maxPower) {
				this.power = this.maxPower;
			}

			this.networkPackNT(150);

		} else {

			this.lastSpin = this.spin;

			if(wasOn) {
				if(this.momentum < 100F)
					this.momentum++;
			} else {
				if(this.momentum > 0)
					this.momentum--;
			}

			this.spin += momentum / 2;

			if(this.spin >= 360) {
				this.spin -= 360F;
				this.lastSpin -= 360F;
			}

			if(momentum > 0) {

				if(audio == null) {
					audio = createAudioLoop();
					audio.startSound();
				} else if(!audio.isPlaying()) {
					audio = rebootAudio(audio);
				}

				audio.keepAlive();
				audio.updateVolume(getVolume(momentum / 50F));
				audio.updatePitch(momentum / 200F + 0.5F + this.afterburner * 0.16F);

			} else {

				if(audio != null) {
					audio.stopSound();
					audio = null;
				}
			}

			/*
			 * All movement related stuff has to be repeated on the client, but only for the client's player
			 * Otherwise this could lead to desync since the motion is never sent form the server
			 */
			if(wasOn && !MainRegistry.proxy.me().capabilities.isCreativeMode) {
				ForgeDirection dir = ForgeDirection.getOrientation(this.getBlockMetadata() - 10).getRotation(ForgeDirection.UP);
				ForgeDirection rot = dir.getRotation(ForgeDirection.UP);

				double minX = this.pos.getX() + 0.5 - dir.offsetX * 3.5 - rot.offsetX * 1.5;
				double maxX = this.pos.getX() + 0.5 - dir.offsetX * 19.5 + rot.offsetX * 1.5;
				double minZ = this.pos.getZ() + 0.5 - dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				double maxZ = this.pos.getZ() + 0.5 - dir.offsetZ * 19.5 + rot.offsetZ * 1.5;

				List<Entity> list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					if(e == MainRegistry.proxy.me()) {
						e.motionX -= dir.offsetX * 0.2;
						e.motionZ -= dir.offsetZ * 0.2;
					}
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 8.5 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 8.5 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					if(e == MainRegistry.proxy.me()) {
						e.motionX -= dir.offsetX * 0.2;
						e.motionZ -= dir.offsetZ * 0.2;
					}
				}

				minX = this.pos.getX() + 0.5 + dir.offsetX * 3.5 - rot.offsetX * 1.5;
				maxX = this.pos.getX() + 0.5 + dir.offsetX * 3.75 + rot.offsetX * 1.5;
				minZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.5 - rot.offsetZ * 1.5;
				maxZ = this.pos.getZ() + 0.5 + dir.offsetZ * 3.75 + rot.offsetZ * 1.5;

				list = this.world.getEntitiesWithinAABB(Entity.class, AxisAlignedBB.getBoundingBox(Math.min(minX, maxX), this.pos.getY(), Math.min(minZ, maxZ), Math.max(minX, maxX), this.pos.getY() + 3, Math.max(minZ, maxZ)));

				for(Entity e : list) {
					if(e == MainRegistry.proxy.me()) {
						e.setInWeb();
					}
				}
			}
		}
	}

public boolean checkRedstone() {
		for(DirPos pos : getConPos()) {
			if(this.world.isBlockIndirectlyGettingPowered(pos.getX(), pos.getY(), pos.getZ())) return true;
		}
		return false;
	}

public short getRelevantMode(boolean useCache) {
		if(useCache) return this.modeCache;
		boolean powered = false;
		for(BlockPos pos : getPortPos()) if(this.world.isBlockIndirectlyGettingPowered(pos.getX(), pos.getY(), pos.getZ())) { powered = true; break; }
		this.modeCache = powered ? this.redHigh : this.redLow;
		return this.modeCache;
	}

public short getRelevantMode(boolean useCache) {
		if(useCache) return this.modeCache;
		this.modeCache = this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ()) ? this.redHigh : this.redLow;
		return this.modeCache;
	}

@Override
	public void update() {
		super.update();
		if(!this.world.isRemote) {

			boolean redstone = this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ());

			if(mode == MODE_REDSTONE && redstone && !lastRedstone) {

				ForgeDirection outputSide = getOutputSide();
				Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ).getBlock();
				IConveyorBelt belt = null;

				if(b instanceof IConveyorBelt) {
					belt = (IConveyorBelt) b;
				}

				int pack = 0;

				for(int i = 0; i < slots.length; i++) {
					if(slots[i] != null) {
						pack++;
					}
				}

				if(belt != null && pack > 0) {

					ItemStack[] box = new ItemStack[pack];

					for(int i = 0; i < slots.length && pack > 0; i++) {

						if(slots[i] != null) {
							pack--;
							box[pack] = slots[i].copy();
							slots[i] = null;
						}
					}

					EntityMovingPackage moving = new EntityMovingPackage(this.world);
					Vec3d pos = new Vec3d(this.pos.getX() + 0.5 + outputSide.offsetX * 0.55, this.pos.getY() + 0.5 + outputSide.offsetY * 0.55, this.pos.getZ() + 0.5 + outputSide.offsetZ * 0.55);
					Vec3d snap = belt.getClosestSnappingPosition(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ, pos);
					moving.setPosition(snap.x, snap.y, snap.z);
					moving.setItemStacks(box);
					this.world.spawnEntityInWorld(moving);
				}
			}

			this.lastRedstone = redstone;

			if(mode != MODE_REDSTONE && this.world.getTotalWorldTime() % 2 == 0) {
				int pack = 1;

				switch(mode) {
				case MODE_4: pack = 4; break;
				case MODE_8: pack = 8; break;
				case MODE_16: pack = 16; break;
				}

				int fullStacks = 0;

				// NO!
				/*StorageManifest manifest = new StorageManifest(); //i wrote some of this for a feature that i scrapped so why not make proper use of it?

				for(int i = 0; i < slots.length; i++) {
					if(slots[i] != null) {
						manifest.writeStack(slots[i]);
					}
				}*/

				for(int i = 0; i < slots.length; i++) {

					if(slots[i] != null && slots[i].stackSize == slots[i].getMaxStackSize()) {
						fullStacks++;
					}
				}

				ForgeDirection outputSide = getOutputSide();
				Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ).getBlock();
				IConveyorBelt belt = null;

				if(b instanceof IConveyorBelt) {
					belt = (IConveyorBelt) b;
				}

				if(belt != null && fullStacks >= pack) {

					ItemStack[] box = new ItemStack[pack];

					for(int i = 0; i < slots.length && pack > 0; i++) {

						if(slots[i] != null && slots[i].stackSize == slots[i].getMaxStackSize()) {
							pack--;
							box[pack] = slots[i].copy();
							slots[i] = null;
						}
					}

					EntityMovingPackage moving = new EntityMovingPackage(this.world);
					Vec3d pos = new Vec3d(this.pos.getX() + 0.5 + outputSide.offsetX * 0.55, this.pos.getY() + 0.5 + outputSide.offsetY * 0.55, this.pos.getZ() + 0.5 + outputSide.offsetZ * 0.55);
					Vec3d snap = belt.getClosestSnappingPosition(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ, pos);
					moving.setPosition(snap.x, snap.y, snap.z);
					moving.setItemStacks(box);
					this.world.spawnEntityInWorld(moving);
				}
			}

			this.networkPackNT(15);
		}
	}

@Override
	public void update() {
		super.update();
		if(!this.world.isRemote) {

			int delay = 20;

			if(slots[19] != null && slots[19].getItem() == ModItems.upgrade_ejector) {
				switch(slots[19].getItemDamage()) {
				case 0: delay = 10; break;
				case 1: delay = 5; break;
				case 2: delay = 2; break;
				}
			}

			if(this.world.getTotalWorldTime() % delay == 0 && !this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ())) {
				int amount = 1;

				if(slots[18] != null && slots[18].getItem() == ModItems.upgrade_stack) {
					switch(slots[18].getItemDamage()) {
					case 0: amount = 4; break;
					case 1: amount = 16; break;
					case 2: amount = 64; break;
					}
				}

				ForgeDirection inputSide = getOutputSide(); // note the switcheroo!
				ForgeDirection outputSide = getInputSide();
				TileEntity te = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX() + inputSide.offsetX, this.pos.getY() + inputSide.offsetY, this.pos.getZ() + inputSide.offsetZ));
				Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ).getBlock();

				int[] access = null;
				ISidedInventory sided = null;

				if(te instanceof ISidedInventory) {
					sided = (ISidedInventory) te;
					//access = sided.getAccessibleSlotsFromSide(dir.ordinal());
					access = masquerade(sided, inputSide.getOpposite().ordinal());
				}

				boolean hasSent = false;

				IConveyorBelt belt = null;

				if(b instanceof IConveyorBelt) {
					belt = (IConveyorBelt) b;
				}

				/* try to send items from a connected inv, if present */
				if(te instanceof IInventory) {

					IInventory inv = (IInventory) te;
					int size = access == null ? inv.getSizeInventory() : access.length;

					for(int i = 0; i < size; i++) {
						int index = access == null ? i : access[i];
						ItemStack stack = inv.getStackInSlot(index);

						if(stack != null && !stack.isEmpty() && (sided == null || sided.canExtractItem(index, stack, com.hbm.lib.ForgeDirection.getOrientation(inputSide.getOpposite().ordinal()).toEnumFacing()))) {

							int maxTarget = Math.min(amount, stack.getMaxStackSize());
							if(this.maxEject && stack.getCount() < maxTarget) continue;
							boolean match = this.matchesFilter(stack);

							if((isWhitelist && match) || (!isWhitelist && !match)) {
								stack = stack.copy();
								int toSend = Math.min(amount, stack.getCount());

								if (belt != null) {
									inv.decrStackSize(index, toSend);
									stack.setCount(toSend);
									sendItem(stack, belt, outputSide);
								} else {
									stack.setCount(toSend);
									ItemStack remaining = InventoryUtil.tryAddItemToInventory(this.slots, 9, 17, stack);
									inv.decrStackSize(index, toSend - (remaining == null ? 0 : remaining.getCount()));
								}
								hasSent = true;
								break;
							}
						}
					}
				}

				/* if no item has been sent, send buffered items while ignoring the filter */
				if(!hasSent && belt != null) {

					for(int i = 9; i < 18; i++) {
						ItemStack stack = slots[i];

						if(stack != null){
							stack = stack.copy();
							int toSend = Math.min(amount, stack.getCount());

							int maxTarget = Math.min(amount, stack.getMaxStackSize());
							if(this.maxEject && stack.getCount() < maxTarget) continue;

							decrStackSize(i, toSend);
							stack.setCount(toSend);
							sendItem(stack, belt, outputSide);

							break;
						}
					}
				}
			}

			this.networkPackNT(15);
		}
	}

@Override
	public void update() {
		super.update();
		if(!this.world.isRemote) {

			int delay = 20;

			if(slots[10] != null && slots[10].getItem() == ModItems.upgrade_ejector) {
				switch(slots[10].getItemDamage()) {
				case 0: delay = 10; break;
				case 1: delay = 5; break;
				case 2: delay = 2; break;
				}
			}

			if(this.world.getTotalWorldTime() >= lastGrabbedTick + delay && !this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ())) {
				int amount = 1;

				if(slots[9] != null && slots[9].getItem() == ModItems.upgrade_stack) {
					switch(slots[9].getItemDamage()) {
					case 0: amount = 4; break;
					case 1: amount = 16; break;
					case 2: amount = 64; break;
					}
				}

				ForgeDirection inputSide = getInputSide();
				ForgeDirection outputSide = getOutputSide();
				Block beltBlock = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ).getBlock();

				//unholy copy paste bullshit because i can't be assed to rework the entire thing
				if(beltBlock instanceof IConveyorBelt) {
					IConveyorBelt belt = (IConveyorBelt) beltBlock;

					double reach = 1D;
					if(this.getBlockMetadata() > 1) { //ignore if pointing up or down
						Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + inputSide.offsetX, this.pos.getY() + inputSide.offsetY, this.pos.getZ() + inputSide.offsetZ).getBlock();
						if(b == ModBlocks.conveyor_double) reach = 0.5D;
						if(b == ModBlocks.conveyor_triple) reach = 0.33D;
					}

					double x = this.pos.getX() + inputSide.offsetX * reach;
					double y = this.pos.getY() + inputSide.offsetY * reach;
					double z = this.pos.getZ() + inputSide.offsetZ * reach;

					List<EntityMovingItem> items = this.world.getEntitiesWithinAABB(EntityMovingItem.class, AxisAlignedBB.getBoundingBox(x + 0.1875D, y + 0.1875D, z + 0.1875D, x + 0.8125D, y + 0.8125D, z + 0.8125D));

					for(EntityMovingItem item : items) {
						if(item.isDead) continue;
						ItemStack stack = item.getItemStack();
						boolean match = this.matchesFilter(stack);
						if(this.isWhitelist && !match || !this.isWhitelist && match) continue;

						lastGrabbedTick = this.world.getTotalWorldTime();

						Vec3d pos = new Vec3d(this.pos.getX() + 0.5 + outputSide.offsetX * 0.55, this.pos.getY() + 0.5 + outputSide.offsetY * 0.55, this.pos.getZ() + 0.5 + outputSide.offsetZ * 0.55);
						Vec3d snap = belt.getClosestSnappingPosition(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ, pos);
						EntityMovingItem newItem = new EntityMovingItem(this.world);
						newItem.setItemStack(item.getItemStack().copy());
						newItem.setPosition(snap.x, snap.y, snap.z);
						item.setDead();
						this.world.spawnEntityInWorld(newItem);
						break;
					}

				} else {

					TileEntity te = this.world.getTileEntity(new net.minecraft.util.math.BlockPos(this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ));

					int[] access = null;
					ISidedInventory sided = null;

					if(te instanceof ISidedInventory) {
						sided = (ISidedInventory) te;
						access = InventoryUtil.masquerade(sided, outputSide.getOpposite().ordinal());
					}

					if(te instanceof IInventory) {

						/*
						 * due to this really primitive way of just offsetting the AABB instead of contracting it, there's a wacky
						 * edge-case where it's possible to feed the grabber by inserting items from the side if there's a triple
						 * lane conveyor in front of the grabbing end. this is such a non-issue that i'm not going to bother trying
						 * to fuck with the AABB further, since that's just a major headache for no practical benefit
						*/
						double reach = 1D;
						if(this.getBlockMetadata() > 1) { //ignore if pointing up or down
							Block b = com.hbm.world.WorldBlockState.read(this.world, this.pos.getX() + inputSide.offsetX, this.pos.getY() + inputSide.offsetY, this.pos.getZ() + inputSide.offsetZ).getBlock();
							if(b == ModBlocks.conveyor_double) reach = 0.5D;
							if(b == ModBlocks.conveyor_triple) reach = 0.33D;
						}

						double x = this.pos.getX() + inputSide.offsetX * reach;
						double y = this.pos.getY() + inputSide.offsetY * reach;
						double z = this.pos.getZ() + inputSide.offsetZ * reach;
						List<EntityMovingItem> items = this.world.getEntitiesWithinAABB(EntityMovingItem.class, AxisAlignedBB.getBoundingBox(x + 0.1875D, y + 0.1875D, z + 0.1875D, x + 0.8125D, y + 0.8125D, z + 0.8125D));

						for(EntityMovingItem item : items) {
							ItemStack stack = item.getItemStack();
							boolean match = this.matchesFilter(stack);
							if(this.isWhitelist && !match || !this.isWhitelist && match) continue;

							lastGrabbedTick = this.world.getTotalWorldTime();

							ItemStack copy = stack.copy();
							int toAdd = Math.min(stack.stackSize, amount);
							copy.stackSize = toAdd;
							ItemStack ret = CraneInserter.addToInventory((IInventory) te, access, copy, outputSide.getOpposite().ordinal());
							int didAdd = toAdd - (ret != null ? ret.stackSize : 0);
							stack.stackSize -= didAdd;

							if(stack.stackSize <= 0) {
								item.setDead();
							}

							amount -= didAdd;
							if(amount <= 0) {
								break;
							}
						}
					}
				}
			}

			this.networkPackNT(15);
		}
	}

@Override
	public void update() {
		super.update();
		if(!this.world.isRemote) {

			if(!this.world.isBlockIndirectlyGettingPowered(this.pos.getX(), this.pos.getY(), this.pos.getZ())) {ForgeDirection outputSide = getOutputSide();
				TileEntity te = Compat.getTileStandard(this.world, this.pos.getX() + outputSide.offsetX, this.pos.getY() + outputSide.offsetY, this.pos.getZ() + outputSide.offsetZ);

				int[] access = null;

				if(te instanceof ISidedInventory) {
					ISidedInventory sided = (ISidedInventory) te;
					access = InventoryUtil.masquerade(sided, outputSide.getOpposite().ordinal());
				}

				boolean didSomething = false;

				if(te instanceof IInventory) {
					for(int i = 0; i < slots.length; i++) {

						ItemStack stack = slots[i];

						if(stack != null) {
							ItemStack ret = CraneInserter.addToInventory((IInventory) te, access, stack.copy(), outputSide.getOpposite().ordinal());

							if(ret == null || ret.stackSize != stack.stackSize) {
								slots[i] = ret;
								this.markDirty();
								didSomething = true;
								break;
							}
						}
					}

					//if the previous operation fails, repeat but use single items instead of the whole stack instead
					//this should fix cases where the inserter can't insert into something that has a stack size limitation
					if(!didSomething) for(int i = 0; i < slots.length; i++) {

						ItemStack stack = slots[i];

						if(stack != null) {
							stack = stack.copy();
							stack.setCount(1);

							ItemStack ret = CraneInserter.addToInventory((IInventory) te, access, stack.copy(), outputSide.getOpposite().ordinal());

							if(ret == null || ret.stackSize != stack.stackSize) {
								this.decrStackSize(i, 1);
								this.markDirty();
								didSomething = true;
								break;
							}
						}
					}
				}
			}

			this.networkPackNT(15);
		}
	}

